public class ProgressiveTaxCalculator {

    public static double taxFor(double income) {
        if (income <= 0) {
            return 0.0;
        }
        double tax = 0.0;
        if (income > 85000) {
            tax += (income - 85000) * 0.30;
            income = 85000;
        }
        if (income > 40000) {
            tax += (income - 40000) * 0.20;
            income = 40000;
        }
        if (income > 10000) {
            tax += (income - 10000) * 0.10;
        }
        return tax;
    }

    public static double topRate(double income) {
        if (income > 85000) {
            return 0.3;
        } else if (income > 40000) {
            return 0.2;
        } else if (income > 10000) {
            return 0.1;
        } else {
            return 0.0;
        }
    }
}
